hooks.command:
python3 -c "
import os, json, sys
try:
    inp = os.environ.get('CLAUDE_TOOL_INPUT', '{}')
    d = json.loads(inp)
    path = d.get('file_path', d.get('path', ''))
    if path and path.endswith('.md') and os.path.exists(path):
        lines = sum(1 for _ in open(path))
        name = os.path.basename(path)
        if lines > 600:
            print(f'[sup] {name}: {lines} lines — prompt files should stay focused')
        else:
            print(f'[sup] {name}: {lines} lines')
except Exception:
    pass
"
